#include "window.h"
#include <memory>
namespace sv {
static QString readSource(const QString& path) { QFile f(path); require(f.open(QIODevice::ReadOnly),"Cannot read "+path); require(f.size()<=256*1024,"Script too large"); return QString::fromUtf8(f.readAll()); }
static void writeSource(const QString& path,const QString& text) { QSaveFile f(path); require(f.open(QIODevice::WriteOnly),"Cannot save "+path); auto b=text.toUtf8(); require(f.write(b)==b.size() && f.commit(),"Cannot commit script"); }
static QStringList chooseSlots(QWidget* parent,const QStringList& current,const QString& title, bool* accepted=nullptr) {
    QDialog dialog(parent); dialog.setWindowTitle(title); QVBoxLayout layout(&dialog); QLabel hint("Select destinations. An empty selection means no output."); layout.addWidget(&hint); QListWidget list; layout.addWidget(&list);
    for(auto s:logicalSlots()) { auto* item=new QListWidgetItem(s,&list); item->setFlags(item->flags()|Qt::ItemIsUserCheckable); item->setCheckState(current.contains(s)?Qt::Checked:Qt::Unchecked); }
    QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel); layout.addWidget(&buttons); QObject::connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept); QObject::connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
    if(accepted)*accepted=false; if(dialog.exec()!=QDialog::Accepted) return current; if(accepted)*accepted=true; QStringList result; for(int i=0;i<list.count();++i) if(list.item(i)->checkState()==Qt::Checked) result<<list.item(i)->text(); return result;
}
Window::Window() {
    setWindowTitle("Stella Vibra"); resize(1400,900);
    try { if(QFileInfo::exists(localPath())) local=readJson(localPath()); } catch(const std::exception& e) { QMessageBox::warning(this,"Local settings",e.what()); }
    local["version"]=1; engine.loadMappings(local["motors"].toObject());
    auto* toolbar=addToolBar("Project"); toolbar->setObjectName("ProjectToolbar");
    auto action=[&](const QString& name,const std::function<void()>& fn){auto* a=toolbar->addAction(name);connect(a,&QAction::triggered,this,[this,fn]{guarded(fn);});return a;};
    action("New",[this]{newProject();}); action("Open",[this]{openProject();}); action("Save",[this]{save();})->setShortcut(QKeySequence::Save);
    action("Apply",[this]{apply();}); action("Run",[this]{require(!project.path.isEmpty(),"Open a project first");engine.run();}); action("Stop",[this]{engine.stop();})->setShortcut(Qt::Key_Escape);
    action("Connect MSFS",[this]{engine.connectSim(local["simconnect_dll"].toString());}); action("Scan Devices",[this]{engine.scanHid();}); action("Settings",[this]{settings();});
    toolbar->addSeparator(); toolbar->addWidget(new QLabel("Edit profile: ")); profile=new QComboBox; profile->addItem("Global",QString()); toolbar->addWidget(profile);
    connect(profile,&QComboBox::currentIndexChanged,this,[this]{if(!refreshing)guarded([this]{rebuildParameters();});});
    auto* left=new QDockWidget("Project Explorer",this); left->setObjectName("Explorer"); auto* leftHost=new QWidget; auto* leftLayout=new QVBoxLayout(leftHost); effectList=new QListWidget; leftLayout->addWidget(effectList);
    auto* add=new QPushButton("Add to Project"); leftLayout->addWidget(add); connect(add,&QPushButton::clicked,this,[this]{guarded([this]{addEffect();});});
    files=new QFileSystemModel(this); files->setReadOnly(true); tree=new QTreeView; tree->setModel(files); for(int i=1;i<4;++i)tree->hideColumn(i); leftLayout->addWidget(tree); left->setWidget(leftHost); addDockWidget(Qt::LeftDockWidgetArea,left);
    connect(effectList,&QListWidget::currentRowChanged,this,[this]{if(!refreshing)guarded([this]{selectEffect();});});
    connect(effectList,&QListWidget::itemChanged,this,[this](QListWidgetItem* item){if(refreshing)return; guarded([&]{ auto id=item->data(Qt::UserRole).toString(); auto old=selectedId; selectedId=id;setValue("","enabled",item->checkState()==Qt::Checked);if(!project.resolved(selectedEffect(),currentAircraft)["enabled"].toBool())engine.disable(id);selectedId=old; });});
    connect(tree,&QTreeView::doubleClicked,this,[this](const QModelIndex& index){guarded([&]{auto path=files->filePath(index);if(!path.endsWith(".lua",Qt::CaseInsensitive))return;auto relative=QDir(QFileInfo(project.path).absolutePath()).relativeFilePath(path);scriptPath(project.path,relative);selectedId.clear();selectedScript=relative;refreshing=true;editor->setPlainText(drafts.contains(relative)?drafts[relative]:readSource(path));refreshing=false;rebuildParameters();});});
    auto* split=new QSplitter(Qt::Vertical); auto* scroll=new QScrollArea; scroll->setWidgetResizable(true);parameterHost=new QWidget;parameters=new QFormLayout(parameterHost);scroll->setWidget(parameterHost);split->addWidget(scroll);
    auto* editHost=new QWidget;auto* editLayout=new QVBoxLayout(editHost);auto* findRow=new QHBoxLayout;auto* search=new QLineEdit;search->setPlaceholderText("Find in script (Enter)");findRow->addWidget(new QLabel("Script Editor"));findRow->addWidget(search);editLayout->addLayout(findRow);editor=new Editor;editLayout->addWidget(editor);split->addWidget(editHost);split->setSizes({300,500});setCentralWidget(split);
    connect(search,&QLineEdit::returnPressed,this,[this,search]{if(!editor->find(search->text())){editor->moveCursor(QTextCursor::Start);editor->find(search->text());}});
    connect(editor,&QPlainTextEdit::textChanged,this,[this]{if(!refreshing && !selectedScript.isEmpty()){drafts[selectedScript]=editor->toPlainText();dirty=true;setWindowModified(true);}});
    auto* right=new QDockWidget("Motor Monitor (sent commands)",this);right->setObjectName("Monitor");auto* rightHost=new QWidget;auto* rightLayout=new QVBoxLayout(rightHost);monitor=new QTableWidget(0,4);monitor->setHorizontalHeaderLabels({"Motor","Slots","Sent","Status"});monitor->setSelectionBehavior(QAbstractItemView::SelectRows);monitor->setSelectionMode(QAbstractItemView::SingleSelection);monitor->setEditTriggers(QAbstractItemView::NoEditTriggers);rightLayout->addWidget(monitor);
    for(auto pair:{std::pair{QString("Mapping"),std::function<void()>([this]{mapping();})},{QString("Test"),std::function<void()>([this]{motorTest();})}}){auto* button=new QPushButton(pair.first);rightLayout->addWidget(button);connect(button,&QPushButton::clicked,this,[this,fn=pair.second]{guarded(fn);});}right->setWidget(rightHost);addDockWidget(Qt::RightDockWidgetArea,right);
    auto* bottom=new QDockWidget("Output",this);bottom->setObjectName("Output");auto* bottomHost=new QWidget;auto* bottomLayout=new QVBoxLayout(bottomHost);auto* logRow=new QHBoxLayout;filter=new QLineEdit;filter->setPlaceholderText("Filter by effect or message");logRow->addWidget(filter);auto* clear=new QPushButton("Clear");logRow->addWidget(clear);bottomLayout->addLayout(logRow);output=new QListWidget;bottomLayout->addWidget(output);bottom->setWidget(bottomHost);addDockWidget(Qt::BottomDockWidgetArea,bottom);
    connect(clear,&QPushButton::clicked,output,&QListWidget::clear);connect(filter,&QLineEdit::textChanged,this,[this]{for(int i=0;i<output->count();++i)output->item(i)->setHidden(!output->item(i)->text().contains(filter->text(),Qt::CaseInsensitive));});
    connect(output,&QListWidget::itemDoubleClicked,this,[this](QListWidgetItem* item){auto match=QRegularExpression("(effects/[^:]+\\.lua):(\\d+):").match(item->text());if(!match.hasMatch())return;guarded([&]{selectedScript=match.captured(1);selectedId.clear();refreshing=true;editor->setPlainText(drafts.value(selectedScript,readSource(scriptPath(project.path,selectedScript))));refreshing=false;auto cursor=editor->textCursor();cursor.setPosition(editor->document()->findBlockByLineNumber(match.captured(2).toInt()-1).position());editor->setTextCursor(cursor);editor->setFocus();});});
    state=new QLabel("MSFS: Disconnected | HID: not scanned | Stopped");statusBar()->addWidget(state,1);
    restoreGeometry(QByteArray::fromBase64(local["geometry"].toString().toLatin1()));restoreState(QByteArray::fromBase64(local["layout"].toString().toLatin1()));
    connect(&timer,&QTimer::timeout,this,[this]{tick();});timer.start(100);addLog("Stopped. Connect and scan explicitly. Apply before Run.");
}
Window::~Window(){engine.stop();}
void Window::guarded(const std::function<void()>& action){try{action();}catch(const std::exception& e){addLog(e.what());QMessageBox::warning(this,"Stella Vibra",e.what());}}
void Window::addLog(const QString& message){auto* item=new QListWidgetItem(message,output);item->setHidden(!message.contains(filter->text(),Qt::CaseInsensitive));while(output->count()>1000)delete output->takeItem(0);output->scrollToBottom();}
bool Window::confirmDiscard(){if(!dirty)return true;auto answer=QMessageBox::question(this,"Unsaved changes","Save changes before continuing?",QMessageBox::Save|QMessageBox::Discard|QMessageBox::Cancel);if(answer==QMessageBox::Cancel)return false;if(answer==QMessageBox::Save)save();return true;}
void Window::closeEvent(QCloseEvent* event){try{if(!confirmDiscard()){event->ignore();return;}engine.stop();saveLocal();event->accept();}catch(const std::exception& e){QMessageBox::warning(this,"Save failed",e.what());event->ignore();}}
void Window::newProject(){if(!confirmDiscard())return;auto folder=QFileDialog::getExistingDirectory(this,"Choose an empty project folder");if(folder.isEmpty())return;require(QDir(folder).entryList(QDir::AllEntries|QDir::NoDotAndDotDot).isEmpty(),"Choose an empty folder");QDir().mkpath(folder+"/effects");QDir().mkpath(folder+"/aircrafts");QJsonArray effects;
    for(auto name:{"ground_roll.lua","touchdown.lua"}){auto source=QCoreApplication::applicationDirPath()+"/effects/"+name;require(QFile::copy(source,folder+"/effects/"+name),"Cannot copy bundled effect: "+source);QJsonObject ports;ports["Center Gear"]=QJsonArray{};ports["Left Gear"]=QJsonArray{"Throttle:1"};ports["Right Gear"]=QJsonArray{"Throttle:2"};effects<<QJsonObject{{"id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"script",QString("effects/")+name},{"enabled",true},{"parameters",QJsonObject{}},{"outputs",ports}};}
    auto path=folder+"/"+QFileInfo(folder).fileName()+".sv";writeJson(path,{{"version",1},{"id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"name",QFileInfo(folder).fileName()},{"game","MSFS2024"},{"effects",effects}});loadProject(path);
}
void Window::openProject(){if(!confirmDiscard())return;auto file=QFileDialog::getOpenFileName(this,"Open Project",{},"Stella Vibra (*.sv)");if(!file.isEmpty())loadProject(file);}
void Window::loadProject(const QString& path){Project next;next.load(path);engine.clearProject();project=std::move(next);drafts.clear();selectedId.clear();selectedScript.clear();dirty=false;refreshing=true;editor->clear();profile->clear();profile->addItem("Global",QString());for(auto key:project.aircraft.keys())profile->addItem(key,key);refreshing=false;refreshExplorer();files->setRootPath(QFileInfo(path).absolutePath());tree->setRootIndex(files->index(QFileInfo(path).absolutePath()));setWindowTitle(project.data["name"].toString()+" — Stella Vibra[*]");setWindowModified(false);apply();}
void Window::save(){require(!project.path.isEmpty(),"No project");for(auto it=drafts.begin();it!=drafts.end();++it)writeSource(scriptPath(project.path,it.key()),it.value());project.save();dirty=false;setWindowModified(false);addLog("Saved. Apply is separate.");}
void Window::apply(){require(!project.path.isEmpty(),"No project");Bundle bundle;bundle.project=project;for(auto v:project.data["effects"].toArray()){auto e=v.toObject();auto relative=e["script"].toString();bundle.sources[relative]=drafts.contains(relative)?drafts[relative]:readSource(scriptPath(project.path,relative));}engine.apply(std::move(bundle));rebuildParameters();addLog("Apply queued; see result in Output.");}
void Window::addEffect(){require(!project.path.isEmpty(),"No project");auto file=QFileDialog::getOpenFileName(this,"Add Lua Effect",QFileInfo(project.path).absolutePath()+"/effects","Lua (*.lua)");if(file.isEmpty())return;auto relative=QDir(QFileInfo(project.path).absolutePath()).relativeFilePath(file);scriptPath(project.path,relative);auto effects=project.data["effects"].toArray();for(auto value:effects)require(value.toObject()["script"]!=relative,"Script already registered");effects<<QJsonObject{{"id",QUuid::createUuid().toString(QUuid::WithoutBraces)},{"script",relative},{"enabled",false},{"parameters",QJsonObject{}},{"outputs",QJsonObject{}}};project.data["effects"]=effects;dirty=true;refreshExplorer();}
QString Window::profileKey()const{return profile->currentData().toString();}
QJsonObject Window::selectedEffect()const{for(auto v:project.data["effects"].toArray())if(v.toObject()["id"]==selectedId)return v.toObject();return {};}
void Window::refreshExplorer(){auto selected=selectedId;refreshing=true;effectList->clear();for(auto v:project.data["effects"].toArray()){auto e=v.toObject();auto* item=new QListWidgetItem(e["script"].toString(),effectList);item->setData(Qt::UserRole,e["id"].toString());item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(project.resolved(e,profileKey())["enabled"].toBool()?Qt::Checked:Qt::Unchecked);if(e["id"]==selected)effectList->setCurrentItem(item);}refreshing=false;}
void Window::selectEffect(){auto* item=effectList->currentItem();if(!item)return;selectedId=item->data(Qt::UserRole).toString();selectedScript=selectedEffect()["script"].toString();refreshing=true;editor->setPlainText(drafts.contains(selectedScript)?drafts[selectedScript]:readSource(scriptPath(project.path,selectedScript)));refreshing=false;rebuildParameters();}
void Window::setValue(const QString& group,const QString& name,const QJsonValue& value,bool reset){
    auto key=profileKey();if(key.isEmpty()){auto array=project.data["effects"].toArray();for(int i=0;i<array.size();++i){auto e=array[i].toObject();if(e["id"]!=selectedId)continue;if(group.isEmpty())e[name]=value;else{auto o=e[group].toObject();if(reset)o.remove(name);else o[name]=value;e[group]=o;}array[i]=e;}project.data["effects"]=array;}
    else{auto patch=project.aircraft.value(key)["effects"].toObject()[selectedId].toObject();if(group.isEmpty()){if(reset)patch.remove(name);else patch[name]=value;}else{auto o=patch[group].toObject();if(reset)o.remove(name);else o[name]=value;if(o.isEmpty())patch.remove(group);else patch[group]=o;}project.setOverride(key,selectedId,patch);}
    dirty=true;setWindowModified(true);
}
void Window::rebuildParameters(){while(parameters->rowCount())parameters->removeRow(0);if(selectedId.isEmpty()){parameters->addRow(new QLabel("Select a registered effect to edit parameters."));return;}auto e=selectedEffect();if(e.isEmpty())return;
    try{LuaEffect meta(selectedId,drafts.contains(selectedScript)?drafts[selectedScript]:readSource(scriptPath(project.path,selectedScript)),selectedScript);meta.configure(project.resolved(e,profileKey()));auto patch=project.aircraft.value(profileKey())["effects"].toObject()[selectedId].toObject();
        parameters->addRow(new QLabel("Draft settings — Apply to activate. PWM rounds to 20 ms ticks."));
        auto addRow=[&](const QString& group,const QString& name,QWidget* widget){auto* row=new QWidget;auto* layout=new QHBoxLayout(row);layout->setContentsMargins(0,0,0,0);layout->addWidget(widget);bool overridden=group.isEmpty()?patch.contains(name):patch[group].toObject().contains(name);layout->addWidget(new QLabel(profileKey().isEmpty()?"Global":overridden?"Aircraft override":"Inherited global/default"));if(!profileKey().isEmpty()){auto* reset=new QPushButton("Reset to Global");layout->addWidget(reset);connect(reset,&QPushButton::clicked,this,[this,group,name]{setValue(group,name,{},true);refreshExplorer();rebuildParameters();});}parameters->addRow(name,row);};
        auto* enabled=new QCheckBox;enabled->setChecked(meta.settings["enabled"].toBool());connect(enabled,&QCheckBox::toggled,this,[this](bool value){setValue("","enabled",value);if(!project.resolved(selectedEffect(),currentAircraft)["enabled"].toBool())engine.disable(selectedId);refreshExplorer();});addRow("","enabled",enabled);
        for(auto p:meta.parameters){auto value=meta.settings["parameters"].toObject()[p.name];if(p.boolean){auto* check=new QCheckBox;check->setChecked(value.toBool());connect(check,&QCheckBox::toggled,this,[this,p](bool v){setValue("parameters",p.name,v);});addRow("parameters",p.name,check);}else{auto* spin=new QDoubleSpinBox;spin->setRange(p.minimum,p.maximum);spin->setDecimals(std::floor(p.step)==p.step?0:3);spin->setSingleStep(p.step);spin->setValue(value.toDouble());if(p.name=="ON ms" || p.name=="Period ms"){auto showEffective=[spin](double v){spin->setSuffix(QString(" (effective %1 ms)").arg(int(std::floor(v/20.0+0.5))*20));};showEffective(spin->value());connect(spin,&QDoubleSpinBox::valueChanged,spin,showEffective);}connect(spin,&QDoubleSpinBox::valueChanged,this,[this,p](double v){setValue("parameters",p.name,v);});addRow("parameters",p.name,spin);}}
        for(auto name:meta.outputs){QStringList current;for(auto v:meta.settings["outputs"].toObject()[name].toArray())current<<v.toString();auto* button=new QPushButton(current.isEmpty()?"No destinations":current.join(", "));connect(button,&QPushButton::clicked,this,[this,name,current]{bool accepted=false;auto chosen=chooseSlots(this,current,"Output: "+name,&accepted);if(!accepted)return;QJsonArray values;for(auto s:chosen)values<<s;setValue("outputs",name,values);rebuildParameters();});addRow("outputs",name,button);}
        for(auto item:meta.unresolved)parameters->addRow(new QLabel("Unresolved (preserved): "+item));
    }catch(const std::exception& error){parameters->addRow(new QLabel(QString("Script error: ")+error.what()));addLog(error.what());}
    refreshExplorer();
}
void Window::tick(){auto snapshot=engine.snapshot();for(const auto& message:snapshot.logs){addLog(message);if(message.startsWith("ERROR "))for(int i=0;i<effectList->count();++i){auto* item=effectList->item(i);if(message.contains(item->data(Qt::UserRole).toString())){QSignalBlocker blocker(effectList);item->setForeground(QColor("#d05050"));item->setToolTip(message);}}}local["motors"]=snapshot.mappings;currentAircraft=snapshot.aircraft;if(!currentAircraft.isEmpty() && profile->findData(currentAircraft)<0)profile->addItem(currentAircraft,currentAircraft);state->setText("MSFS: "+snapshot.sim+" | HID: "+QString::number(std::count_if(snapshot.motors.begin(),snapshot.motors.end(),[](const Motor& motor){return motor.connected;}))+" motors connected | Aircraft: "+(currentAircraft.isEmpty()?"Unknown":currentAircraft)+" | "+snapshot.execution);
    QString selected;if(monitor->currentRow()>=0 && monitor->item(monitor->currentRow(),0))selected=monitor->item(monitor->currentRow(),0)->data(Qt::UserRole).toString();monitor->setRowCount(snapshot.motors.size());for(int i=0;i<snapshot.motors.size();++i){const auto& m=snapshot.motors[i];QStringList values{m.label,m.destinations.isEmpty()?"Unassigned":m.destinations.join(", "),QString::number(m.sent),!m.error.isEmpty()?m.error:m.ambiguous?"Manual assignment required":m.connected?"Connected":"Disconnected"};for(int j=0;j<4;++j){auto* item=new QTableWidgetItem(values[j]);if(j==0)item->setData(Qt::UserRole,m.id);monitor->setItem(i,j,item);}if(m.id==selected)monitor->selectRow(i);} }
void Window::saveLocal(){local["version"]=1;local["geometry"]=QString::fromLatin1(saveGeometry().toBase64());local["layout"]=QString::fromLatin1(saveState().toBase64());writeJson(localPath(),local);}
void Window::settings(){auto path=QFileDialog::getOpenFileName(this,"Select official x64 SimConnect.dll",local["simconnect_dll"].toString(),"SimConnect (SimConnect.dll)");if(path.isEmpty())return;local["simconnect_dll"]=path;saveLocal();addLog("SimConnect path saved. Use Connect MSFS to connect.");}
void Window::mapping(){int row=monitor->currentRow();require(row>=0,"Select a motor");auto id=monitor->item(row,0)->data(Qt::UserRole).toString();QStringList current;for(auto v:local["motors"].toObject()[id].toObject()["slots"].toArray())current<<v.toString();bool accepted=false;auto chosen=chooseSlots(this,current,"Motor Mapping",&accepted);if(!accepted)return;engine.mapMotor(id,chosen);tick();saveLocal();}
void Window::motorTest(){int row=monitor->currentRow();require(row>=0,"Select a motor");auto id=monitor->item(row,0)->data(Qt::UserRole).toString();QDialog dialog(this);dialog.setWindowTitle("Motor Test — "+monitor->item(row,0)->text());QFormLayout layout(&dialog);QSpinBox strength,on,period,duration;strength.setRange(0,255);strength.setValue(1);on.setRange(0,5000);on.setValue(20);period.setRange(20,5000);period.setValue(80);duration.setRange(1,5000);duration.setValue(3000);QCheckBox pwm("PWM");QLabel effective;layout.addRow("Strength",&strength);layout.addRow(&pwm);layout.addRow("ON ms",&on);layout.addRow("Period ms",&period);layout.addRow("Duration ms (max 5000)",&duration);layout.addRow(&effective);auto update=[&]{effective.setText(QString("Effective PWM: %1 / %2 ms").arg(int(std::floor(on.value()/20.0+0.5))*20).arg(int(std::floor(period.value()/20.0+0.5))*20));};connect(&on,&QSpinBox::valueChanged,&dialog,update);connect(&period,&QSpinBox::valueChanged,&dialog,update);update();QPushButton start("Start"),stop("Stop");layout.addRow(&start,&stop);connect(&start,&QPushButton::clicked,&dialog,[&]{guarded([&]{engine.test(id,pwm.isChecked()?Mode::Pwm:Mode::Constant,strength.value(),on.value(),period.value(),duration.value());});});connect(&stop,&QPushButton::clicked,&dialog,[this]{engine.stopTest();});dialog.exec();engine.stopTest();}
}
